  ('demo-observation-demo-observation-home-2', 'demo-hospitation-hilfsmittel-homecare', 2, 'Statusklärung erfolgt über Hotline', 'Die Portalsuche liefert keinen eindeutigen Stand.', 'Die Sachbearbeiterin ruft die Kostenträger-Hotline an. Sie nennt beide Vorgangsnummern. Sie überträgt die mündliche Auskunft in das Auftragssystem.', 'Kommunikation mit anderen Einrichtungen', 'fehlende Information', 'Prozessverzögerung', 'Reibung / Problem', 'interpreted', NULL, NULL, ARRAY['Sachbearbeitung'::text, 'Kostenträger'::text]::text[], ARRAY[]::text[], ARRAY['Statusklärung'::text]::text[], '{"id":"demo-observation-demo-observation-home-2","sequence":2,"observedAt":"09:28 Uhr","title":"Statusklärung erfolgt über Hotline","situationContext":"Die Portalsuche liefert keinen eindeutigen Stand.","trigger":"Der Auftrag soll für die Tourenplanung freigegeben werden.","observed":"Die Sachbearbeiterin ruft die Kostenträger-Hotline an. Sie nennt beide Vorgangsnummern. Sie überträgt die mündliche Auskunft in das Auftragssystem.","actions":["Die Sachbearbeiterin ruft die Kostenträger-Hotline an.","Sie nennt beide Vorgangsnummern.","Sie überträgt die mündliche Auskunft in das Auftragssystem."],"toolsAndDocuments":["Telefon","Kostenträgerportal","Auftragssystem"],"communicationChannels":["Telefon"],"immediateConsequence":"Die Lieferung bleibt bis zur schriftlichen Bestätigung zurückgestellt.","affectedRoles":["Sachbearbeitung","Kostenträger"],"processPhase":"Kommunikation mit anderen Einrichtungen","problemType":"fehlende Information","impact":"Prozessverzögerung","observationType":"Reibung / Problem","currentWorkaround":"Telefonische Statusklärung mit manueller Übertragung.","settingType":"Homecare","theme":"Statusklärung","evidenceType":"interpreted","sourceType":"synthetic_source_scenario","sourceReference":"Fachlicher Quellenbezug 02 · https://www.g-ba.de/presse/pressemitteilungen-meldungen/595/","uncertainty":"Die konkrete Situation ist ein synthetischer Fall. Sie belegt weder Häufigke