  ('demo-observation-demo-observation-reha-2', 'demo-hospitation-reha-nachsorge', 2, 'Abweichung wird im Übergabeblatt sichtbar gemacht', 'Nach Rückruf der Physiotherapiepraxis.', 'Die Koordinatorin streicht das frühere Datum. Sie trägt den bestätigten Termin in das Übergabeblatt ein. Sie legt das Blatt oben auf die Patientenmappe.', 'Befund / Dokumentation', 'positives Muster / Best Practice', 'Ablauf funktioniert gut', 'positives Beispiel', 'interpreted', NULL, NULL, ARRAY['Reha-Koordination'::text, 'Patient'::text]::text[], ARRAY[]::text[], ARRAY['Übergabe'::text]::text[], '{"id":"demo-observation-demo-observation-reha-2","sequence":2,"observedAt":"14:08 Uhr","title":"Abweichung wird im Übergabeblatt sichtbar gemacht","situationContext":"Nach Rückruf der Physiotherapiepraxis.","trigger":"Der spätere Starttermin wird bestätigt.","observed":"Die Koordinatorin streicht das frühere Datum. Sie trägt den bestätigten Termin in das Übergabeblatt ein. Sie legt das Blatt oben auf die Patientenmappe.","actions":["Die Koordinatorin streicht das frühere Datum.","Sie trägt den bestätigten Termin in das Übergabeblatt ein.","Sie legt das Blatt oben auf die Patientenmappe."],"toolsAndDocuments":["Übergabeblatt","Patientenmappe"],"communicationChannels":[],"immediateConsequence":"Im Abschlussgespräch wird nur noch ein Startdatum kommuniziert.","affectedRoles":["Reha-Koordination","Patient"],"processPhase":"Befund / Dokumentation","problemType":"positives Muster / Best Practice","impact":"Ablauf funktioniert gut","observationType":"positives Beispiel","currentWorkaround":"","settingType":"Reha","theme":"Übergabe","evidenceType":"interpreted","sourceType":"synthetic_source_scenario","sourceReference":"Fachlicher Quellenbezug 03 · https://www.bundesgesundheitsministerium.de/service/begriffe-von-a-z/e/entlassmanagement/seite","uncertainty":"Die konkrete Situation ist ein synthetischer Fall. Sie belegt weder Häufigkeit noch Kausalität.","internalUseAllowed":true,"externalUseAllowed":fa