  ('demo-observation-demo-observation-krise-3', 'demo-hospitation-psychosozialer-krisenpfad', 3, 'Übergabe wird in zwei Dokumentationen nachgetragen', 'Nach Abschluss der telefonischen Koordination.', 'Die Psychotherapeutin überträgt die Notizen in die Patientenakte. Die Assistenz dokumentiert Zeitpunkt und Zielklinik im Krisenregister. Das Papierblatt wird bis zur Gegenprüfung aufbewahrt.', 'Befund / Dokumentation', 'doppelte Dokumentation', 'Zeitaufwand', 'Reibung / Problem', 'interpreted', NULL, NULL, ARRAY['Psychotherapeutin'::text, 'Praxisassistenz'::text]::text[], ARRAY[]::text[], ARRAY['Dokumentation'::text]::text[], '{"id":"demo-observation-demo-observation-krise-3","sequence":3,"observedAt":"15:06 Uhr","title":"Übergabe wird in zwei Dokumentationen nachgetragen","situationContext":"Nach Abschluss der telefonischen Koordination.","trigger":"Die unmittelbare Übergabe ist beendet.","observed":"Die Psychotherapeutin überträgt die Notizen in die Patientenakte. Die Assistenz dokumentiert Zeitpunkt und Zielklinik im Krisenregister. Das Papierblatt wird bis zur Gegenprüfung aufbewahrt.","actions":["Die Psychotherapeutin überträgt die Notizen in die Patientenakte.","Die Assistenz dokumentiert Zeitpunkt und Zielklinik im Krisenregister.","Das Papierblatt wird bis zur Gegenprüfung aufbewahrt."],"toolsAndDocuments":["Patientenakte","Krisenregister","Krisenblatt"],"communicationChannels":[],"immediateConsequence":"Dieselben Kerndaten werden in zwei Systemen und vorübergehend auf Papier geführt.","affectedRoles":["Psychotherapeutin","Praxisassistenz"],"processPhase":"Befund / Dokumentation","problemType":"doppelte Dokumentation","impact":"Zeitaufwand","observationType":"Reibung / Problem","currentWorkaround":"Nachträglicher Abgleich von Patientenakte und Krisenregister.","settingType":"Psychosoziale Praxis","theme":"Dokumentation","evidenceType":"interpreted","sourceType":"synthetic_source_scenario","sourceReference":"Fachlicher Quellenbezug 05 · https://www.g-ba.de/richtlinien/87/","uncertainty":"Die konkrete Situation ist ein synthetischer Fall. Sie belegt weder Häufigkeit noch Kausalität.","internalUseAllowed":true,"externalUseAllowed":false,"createdAt":"2026-07-25T12:00:00.000Z","updatedAt":"2026-07-25T12:00:00.000Z","originalId":"demo-observation-krise-3","hospitationId":"demo-hospitation-psychosozialer-krisenpfad","originalEvidenceType":"synthetic_source_based","seedNamespace":"pre-gematik-synthetic-v1"}'::jsonb, 'active', NULL, NULL, '2026-07-25T12:00:00.000Z', 'demo-profile-admin', '2026-07-25T12:00:00.000Z', 'demo-profile-admin'),
  ('demo-observation-demo-observation-info-1', 'demo-hospitation-patienteninformation-entlassung', 1, 'Medizinischer Arztbrief beantwortet die Alltagsfragen nicht', 'Vorbereitung eines Entlassgesprächs.', 'Die Pflegefachperson sucht die Änderung im Arztbrief. Sie gleicht sie mit dem Medikationsplan ab. Sie markiert die Änderung im Patientenblatt.', 'Kommunikation mit Patient:innen', 'Systemverständnis', 'Sicherheitsgefühl sinkt', 'Reibung / Problem', 'interpreted', NULL, NULL, ARRAY['Pflegefachperson'::text, 'Patient'::text]::text[], ARRAY[]::text[], ARRAY['Medikationsverständnis'::text]::text[], '{"id":"demo-observation-demo-observation-info-1","sequence":1,"observedAt":"10:42 Uhr","title":"Medizinischer Arztbrief beantwortet die Alltagsfragen nicht","situationContext":"Vorbereitung eines Entlassgesprächs.","trigger":"Der Patient fragt, welches Medikament abends nicht mehr eingenommen werden soll.","observed":"Die Pflegefachperson sucht die Änderung im Arztbrief. Sie gleicht sie mit dem Medikationsplan ab. Sie markiert die Änderung im Patientenblatt.","actions":["Die Pflegefachperson sucht die Änderung im Arztbrief.","Sie gleicht sie mit dem Medikationsplan ab.","Sie markiert die Änderung im Patientenblatt."],"toolsAndDocuments":["Arztbrief","Medikationsplan","Patientenblatt"],"communicationChannels":[],"immediateConsequence":"Die konkrete Einnahmeänderung wird im Gespräch sichtbar hervorgehoben.","affectedRoles":["Pflegefachperson","Patient"],"processPhase":"Kommunikation mit Patient:innen","problemType":"Systemverständnis","impact":"Sicherheitsgefühl sinkt","observationType":"Reibung / Problem","currentWorkaround":"Zusätzliches laienverständliches Patientenblatt.","settingType":"Klinik / Entlassmanagement","theme":"Medikationsverständnis","evidenceType":"interpreted","sourceType":"synthetic_source_scenario","sourceReference":"Fachlicher Quellenbezug 03 · https://www.bundesgesundheitsministerium.de/service/begriffe-von-a-z/e/entlassmanagement/seite","uncertainty":